class Node(object):
	start = None
	end = None

	def __init__(self, s, e):
		self.start = s
		self.end = e
nodes = []

def do_append(p, q):
	p_index = find_index(p)
	q_index = find_index(q)
	if p_index is None and q_index is None:
		nodes.append(Node(p, q))
		return
	elif q_index is None:
		if p_index < 0:
			nodes[abs(p_index) - 1].start = p
		nodes[abs(p_index) - 1].end = q
		last_node = len(nodes)
		while last_node > abs(p_index):
			last_node -= 1
			del nodes[last_node]
		normalize(abs(p_index) - 1)
		return
	elif p_index == -1:
		if q_index == -1:
			nodes.insert(0, Node(p, q))
			normalize(0)
			return
		else:
			nodes[0].start = p
			p_index = 1
	if p_index < 0:
		p_index += 1
	else:
		p_index -= 1
	if q_index < 0:
		q_index += 1
	else:
		q_index -= 1
	if p_index == q_index:
		if p_index <= 0 and nodes[abs(p_index)].start > p:
			nodes.insert(-1 * p_index, Node(p, q))
			normalize(abs(p_index))
	else:
		next_node = abs(p_index) + 1
		while next_node < abs(q_index):
			del nodes[abs(p_index) + 1]
			next_node += 1
		if p_index < 0:
			nodes[abs(p_index)].start = p
		if q_index < 0:
			nodes[abs(p_index)].end = q
		elif abs(q_index) != abs(p_index):
			new_end = nodes[abs(p_index) + 1].end
			del nodes[abs(p_index) + 1]
			nodes[abs(p_index)].end = new_end
		normalize(abs(p_index))

def normalize(index):
	again = False
	if index >= len(nodes) or index < 0:
		return
	if index > 0 and nodes[index - 1].end + 1 == nodes[index].start:
		nodes[index - 1].end = nodes[index].end
		del nodes[index]
		again = True
		if 1 < index < len(nodes) and nodes[index - 1].end + 1 == nodes[index].start:
			nodes[index - 1].end = nodes[index].end
			del nodes[index]
			again = True
	elif index + 1 < len(nodes) and nodes[index + 1].start - 1 == nodes[index].end:
		nodes[index].end = nodes[index + 1].end
		del nodes[index + 1]
		again = True
	if again:
		normalize(index)

def find_index(p, start_index=0):
	ind = start_index
	while ind < len(nodes):
		if nodes[ind].end >= p >= nodes[ind].start:
			return ind + 1
		elif nodes[ind].start > p:
			return -1 * (ind + 1)
		ind += 1
	return None
(n, l, r) = map(int, input().split())
lengths = list(map(int, input().split()))
lengths.sort()
i = 0
while i < n - 1:
	j = i + 1
	sums = lengths[i] + lengths[j]
	diff = abs(lengths[i] - lengths[j])
	if l > diff:
		start = l
	else:
		start = diff + 1
	if start < sums and start <= r:
		if sums <= r:
			end = sums - 1
		else:
			end = r
		if start <= end:
			do_append(start, end)
	i += 1
count = 0
for node in nodes:
	count = count + node.end - node.start + 1
print(count)
